<script setup>
import {ref,computed,inject,onMounted,onBeforeUnmount,watch} from 'vue'


import PageHeader from '../../shared/components/PageHeader.vue'
import StatePanel from '../../shared/components/StatePanel.vue'

import {requestJSON,useAsyncData} from '../../shared/composables/asyncData.js'
import {toast} from '../../shared/composables/toast.js'
import {arthasQuickCommands,arthasNeedsConfirmation,arthasScopeChanged,arthasStateLabel,appendArthasOutput,arthasDiagnostics,matchesArthasSample} from '../arthas.js'
import ArthasDiagnosticResult from '../components/ArthasDiagnosticResult.vue'
import ArthasDeploymentConnect from '../components/ArthasDeploymentConnect.vue'
const deploymentConnect=ref(null),onboarding=ref(false)
const service=inject('curSvc',ref('')),environment=inject('curEnvironment',ref(''))
const me=ref(null),checking=ref(true),identityError=ref(''),admin=computed(()=>me.value?.role==='admin')
const {data:targets,loading,error,load:readTargets}=useAsyncData([])
const selected=ref(''),session=ref(null),username=ref('arthas'),password=ref(''),connecting=ref(false),disconnecting=ref(false)
const command=ref(''),executing=ref(false),interrupting=ref(false),uncertain=ref(false),outputs=ref([]),interrupted=ref(false)
const target=computed(()=>targets.value.find(t=>t.id===selected.value)),scopeChanged=computed(()=>arthasScopeChanged(session.value?.target,service.value,environment.value))
const mode=ref('common'),useSaved=ref(false),diagnosing=ref(''),diagnosis=ref(null),diagnosticError=ref('')
let diagnosticGeneration=0,diagnosticRequest
watch(target,t=>{useSaved.value=!!t?.has_credential;password.value='';username.value='arthas'})
watch([service,environment,selected],()=>{diagnosticGeneration++;diagnosticRequest?.abort();diagnosing.value='';diagnosis.value=null;diagnosticError.value=''})
const editing=ref(false),saving=ref(false),removing=ref(false),confirming=ref(false),form=ref({}),formError=ref(''),auditOpen=ref(false),audits=ref([]),auditLoading=ref(false),auditError=ref('')
const targetForm=ref(null),nameInput=ref(null),serviceInput=ref(null),environmentInput=ref(null),endpointInput=ref(null)
const targetRules={name:[{required:true,message:'请填写连接名称'}],service:[{required:true,message:'请填写应用标识'}],environment:[{required:true,message:'请填写环境标识'}],endpoint:[{required:true,message:'请填写 Arthas HTTP 根地址'}]}
let generation=0,request,disposed=false
watch([executing,confirming,connecting,disconnecting,saving,editing,command,session,diagnosing,onboarding],()=>{if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:!!session.value||editing.value||!!command.value.trim(),busy:executing.value||confirming.value||connecting.value||disconnecting.value||saving.value||!!diagnosing.value||onboarding.value},location.origin)})
async function deploymentConnected(result){await loadTargets();if(targets.value.some(t=>t.id===result.id))selected.value=result.id;toast('部署实例已接入 Arthas，可直接选择常用诊断；未执行诊断命令','success')}
const api=(path,method='GET',body,options={})=>requestJSON('api/arthas/'+path,{method,...(body===undefined?{}:{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),...options})
async function loadTargets(){if(!admin.value)return;const ok=await readTargets(signal=>api('targets?'+new URLSearchParams({service:service.value,environment:environment.value}),'GET',undefined,{signal}));if(ok&&!session.value&&!targets.value.some(t=>t.id===selected.value))selected.value=targets.value.length===1?targets.value[0].id:''}
async function identity(){checking.value=true;identityError.value='';try{me.value=await requestJSON('/api/me');await loadTargets()}catch(e){identityError.value=e.message}finally{checking.value=false}}
onMounted(identity)
watch([service,environment],loadTargets)
function edit(t){formError.value='';form.value={...(t?{...t}:{name:'',service:service.value,environment:environment.value,endpoint:''}),credential_username:'arthas',credential_password:'',clear_credential:false};editing.value=true}
function cancelConfig(){if(saving.value)return;editing.value=false;formError.value='';form.value.credential_password=''}
async function diagnose(key){
 if(diagnosing.value||!target.value||session.value)return
 const snapshot={...target.value},current=++diagnosticGeneration
 diagnosing.value=key;diagnosticError.value='';diagnosis.value=null;diagnosticRequest=new AbortController()
 try{
  const result=await api('diagnose','POST',{target_id:snapshot.id,revision:snapshot.revision,service:snapshot.service,environment:snapshot.environment,diagnostic:key},{signal:diagnosticRequest.signal})
  if(current!==diagnosticGeneration||disposed)return
  if(!matchesArthasSample(result,snapshot))throw Error('诊断结果目标不一致，请核对')
  diagnosis.value=result
 }catch(e){if(current===diagnosticGeneration&&!disposed)diagnosticError.value=e.message}finally{if(current===diagnosticGeneration)diagnosing.value=''}
}
async function save(){
 if(saving.value)return
 saving.value=true;formError.value=''
 try{
  const errors=await validateFields(targetForm.value,form.value,targetRules,_validationErrors)
  if(errors){focusControl(({name:nameInput,service:serviceInput,environment:environmentInput,endpoint:endpointInput}[Object.keys(errors)[0]])?.value);return}
  const t=form.value,payload={name:t.name,service:t.service,environment:t.environment,endpoint:t.endpoint,...(t.id?{id:t.id,revision:t.revision}:{}),...(t.credential_password?{credential:{username:t.credential_username||'arthas',password:t.credential_password}}:{}),...(t.clear_credential?{clear_credential:true}:{})}
  const result=await api('targets'+(t.id?'/'+encodeURIComponent(t.id):''),t.id?'PUT':'POST',payload)
  editing.value=false;form.value.credential_password='';diagnosis.value=null;await loadTargets();if(targets.value.some(t=>t.id===result.id))selected.value=result.id
  toast('Arthas 连接已保存；未连接或执行命令','success')
 }catch(e){formError.value=e.message;focusControl(endpointInput.value)}finally{saving.value=false}
}
async function remove(){if(!target.value||session.value||removing.value)return;removing.value=true;const t={...target.value};try{if(!await confirmAction('仅从可选连接中移除“'+t.name+'”，不停止 Arthas 或 JVM，保留诊断审计。','移除 Arthas 连接'))return;await api('targets/'+encodeURIComponent(t.id),'DELETE',{revision:t.revision});selected.value='';await loadTargets();toast('连接已移除','success')}catch(e){toast(e.message,'error')}finally{removing.value=false}}
async function connect(){if(connecting.value||session.value||!target.value)return;const t={...target.value},current=++generation;connecting.value=true;try{const result=await api('sessions','POST',{target_id:t.id,revision:t.revision,...(useSaved.value?{use_saved_credential:true}:{username:username.value,password:password.value})});if(disposed||current!==generation){api('sessions/'+encodeURIComponent(result.id),'DELETE').catch(()=>{});return}session.value=result;outputs.value=[];command.value='';uncertain.value=false;toast('已连接 '+t.name+'；尚未执行诊断命令','success')}catch(e){if(!disposed)toast(e.message,'error')}finally{password.value='';connecting.value=false}}
async function disconnect(){if(!session.value||disconnecting.value)return;disconnecting.value=true;const old=session.value;try{const result=await api('sessions/'+encodeURIComponent(old.id),'DELETE');generation++;request?.abort();session.value=null;command.value='';uncertain.value=false;executing.value=false;toast(result.remote_closed===false?'已关闭平台会话；目标关闭结果未确认，请核对 Arthas':'已断开诊断会话，不停止 JVM',result.remote_closed===false?'warning':'success');await loadTargets()}catch(e){uncertain.value=true;toast(e.message,'error')}finally{disconnecting.value=false}}
async function execute(){
 if(!session.value||executing.value||confirming.value||disconnecting.value||scopeChanged.value||uncertain.value||!command.value.trim())return
 const text=command.value.trim(),snapshot=session.value
 if(arthasNeedsConfirmation(text)){confirming.value=true;try{if(!await confirmAction('目标：'+snapshot.target.service+' / '+snapshot.target.environment+' / '+snapshot.target.name+'。所填命令可能读取敏感数据或修改 JVM；执行最长 10 秒，失败不会自动重试。确认执行？','确认 Arthas 诊断操作'))return}finally{confirming.value=false}}
 if(session.value?.id!==snapshot.id||scopeChanged.value)return
 const current=generation;interrupted.value=false;executing.value=true;request=new AbortController()
 const row={id:Date.now(),command:text,state:'executing',output:'',target:snapshot.target.name};outputs.value=appendArthasOutput(outputs.value,row)
 try{const result=await api('sessions/'+encodeURIComponent(snapshot.id)+'/execute','POST',{command:text,confirm:arthasNeedsConfirmation(text)},{signal:request.signal});if(current!==generation||disposed)return;Object.assign(row,{...result,state:interrupted.value?'interrupted':result.state});outputs.value=[...outputs.value];if(result.state==='unknown')uncertain.value=true}
 catch(e){if(current!==generation||disposed)return;row.state='unknown';row.output=e.message;uncertain.value=true;outputs.value=[...outputs.value]}
 finally{if(current===generation)executing.value=false}
}
async function interrupt(){if(!session.value||interrupting.value)return;interrupting.value=true;try{await api('sessions/'+encodeURIComponent(session.value.id)+'/interrupt','POST',{});interrupted.value=true;uncertain.value=false;toast('已请求中断当前命令；已发生的修改不会回滚','warning')}catch(e){toast(e.message,'error')}finally{interrupting.value=false}}
async function loadAudit(){auditLoading.value=true;auditError.value='';try{audits.value=await api('audit')}catch(e){auditError.value=e.message}finally{auditLoading.value=false}}
async function openAudit(){auditOpen.value=true;await loadAudit()}
onBeforeUnmount(()=>{disposed=true;generation++;diagnosticGeneration++;diagnosticRequest?.abort();request?.abort();password.value='';form.value.credential_password='';if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:false,busy:false},location.origin);if(session.value)api('sessions/'+encodeURIComponent(session.value.id),'DELETE',undefined,{keepalive:true}).catch(()=>{})})

import OptionPicker from '../../shared/components/OptionPicker.vue'

import {RefreshCwIcon as IconRefresh,PlusIcon as IconPlus} from '@lucide/vue'

import {confirmAction} from '../../shared/shadcnFeedback.js'

import {reactive as _validationReactive} from 'vue'
import {validateFields,setFieldErrors,scrollToValidationField} from '../../shared/formValidation.js'
const _validationErrors=_validationReactive({})

import {focusControl} from '../../shared/focusControl.js'


import {Badge,Button,Checkbox,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsContent,TabsList,TabsTrigger,Textarea} from '../../shared/shadcn-ui.js'
</script>
<template><div class="arthas-page"><PageHeader title="Arthas 诊断控制台" help="选择已部署的 Java 主机或 Docker 实例，由平台检测 JVM 并接入 Arthas，无需手动启动或填写地址。接入后可使用常用诊断和已授权的 MCP。已有外部 Arthas 可通过手动连接添加；单次诊断最长 10 秒。"><template v-if="admin" #actions><Button @click="deploymentConnect.open()" variant="default" size="default" type="button" :disabled="(!!session||connecting||!!diagnosing||onboarding)"><IconPlus/>接入部署实例</Button><Button @click="edit()" variant="outline" size="default" type="button" :disabled="(!!session||connecting||!!diagnosing||onboarding)">手动连接</Button><Button @click="openAudit" variant="outline" size="default" type="button">诊断审计</Button><Button aria-label="刷新 Arthas 连接" @click="loadTargets" variant="outline" size="default" type="button" :disabled="(!!diagnosing)||(loading)"><Spinner v-if="loading"/><IconRefresh/></Button></template></PageHeader><div v-if="checking" tip="正在检查访问权限…" class="relative min-w-0" :aria-busy="true"><div v-if="true" class="flex items-center justify-center gap-2 p-4" role="status"><Spinner/><span class="sr-only">正在读取</span></div></div><StatePanel v-else-if="identityError" :error="true" title="权限信息读取失败" :message="identityError"><Button @click="identity" variant="outline" size="default" type="button">重试</Button></StatePanel><Empty v-else-if="!admin"><EmptyHeader><EmptyDescription>{{"Arthas 可执行高权限 JVM 命令，仅平台管理员可使用。普通监控功能不受影响。"}}</EmptyDescription></EmptyHeader></Empty><template v-else><Tabs :model-value="mode" @update:model-value="mode=$event;"><div class="flex min-w-0 items-center gap-2"><TabsList class="h-auto! max-w-full flex-wrap gap-y-1 [&>[data-slot=tabs-trigger]]:h-7"><TabsTrigger :disabled="!!session||executing||connecting" :value="&quot;common&quot;">常用诊断</TabsTrigger><TabsTrigger :disabled="!!diagnosing" :value="&quot;advanced&quot;">高级控制台</TabsTrigger></TabsList></div><TabsContent :disabled="!!session||executing||connecting" :value="&quot;common&quot;" force-mount v-show="!(mode!==&quot;common&quot;)" class="min-w-0"></TabsContent><TabsContent :disabled="!!diagnosing" :value="&quot;advanced&quot;" force-mount v-show="!(mode!==&quot;advanced&quot;)" class="min-w-0"></TabsContent></Tabs><StatePanel v-if="error" :error="true" title="连接列表读取失败" :message="error"><Button @click="loadTargets" variant="outline" size="default" type="button">重试</Button></StatePanel><section class="arthas-connection"><div v-if="session" class="arthas-session-target"><Badge :variant="(&quot;green&quot;)==='red'?'destructive':'secondary'">已建立会话</Badge><strong>{{session.target.name}}</strong><span>{{session.target.service}} / {{session.target.environment}}</span><span>{{session.target.managed?'SSH 私有通道':session.target.endpoint}}</span><Button @click="disconnect" variant="outline" size="default" type="button" :disabled="(disconnecting)"><Spinner v-if="disconnecting"/>断开</Button></div><template v-else><fieldset class="arthas-connect-form min-w-0" ><Field class="arthas-instance"><FieldLabel>诊断实例</FieldLabel><OptionPicker v-model="selected" aria-label="诊断连接" placeholder="选择应用、环境对应的实例" :disabled="connecting||!!diagnosing" class="min-w-36" :options="[...(targets).map((t)=>({value:t.id,label:String(t.name)+&quot; · &quot;+String(t.service)+&quot; / &quot;+String(t.environment)}))]"/></Field><template v-if="mode==='advanced'"><Field v-if="target?.has_credential"><FieldLabel>认证方式</FieldLabel><FieldLabel class="flex items-center gap-2 font-normal"><Checkbox v-model="useSaved"/>使用已配置认证</FieldLabel></Field><template v-if="!useSaved&&!target?.managed"><Field><FieldLabel>Arthas 用户名</FieldLabel><Input v-model="username" aria-label="Arthas 用户名" :disabled="connecting" autocomplete="off"/></Field><Field><FieldLabel>临时密码</FieldLabel><Input v-model="password" aria-label="Arthas 密码" :disabled="connecting" autocomplete="new-password" allow-clear type="password"/><FieldDescription>仅当前会话使用，不保存。</FieldDescription></Field></template></template><div class="arthas-connect-actions"><Button v-if="mode==='advanced'" @click="connect" variant="default" size="default" type="button" :disabled="(!target||loading||!!error)||(connecting)"><Spinner v-if="connecting"/>连接</Button><Badge v-if="target&&mode==='common'" variant="secondary">{{target.managed?'平台管理 · SSH 私有通道':target.has_credential?'使用已配置认证':'未配置认证；如目标要求密码，请先配置连接'}}</Badge><Button v-if="!target?.managed" @click="edit(target)" variant="outline" size="default" type="button" :disabled="(!target||connecting||!!diagnosing)">编辑连接</Button><Button @click="remove" class="text-destructive" :variant="'destructive'" size="default" type="button" :disabled="(!target||connecting||!!diagnosing)||(removing)"><Spinner v-if="removing"/>移除</Button></div></fieldset><Empty v-if="!loading&&!error&&!targets.length"><EmptyHeader><EmptyDescription>{{"当前范围尚未接入 Arthas 实例"}}</EmptyDescription></EmptyHeader></Empty></template></section><p v-if="scopeChanged" role="alert" class="arthas-warning">应用或环境已切换；当前会话仍属于 {{session.target.service}} / {{session.target.environment}}，请先断开并重新选择连接。</p><p v-if="uncertain" role="alert" class="arthas-warning">上条命令结果未确认，不会自动重试。请先请求中断或断开，再核对目标状态；这不会回滚已发生的修改。</p><template v-if="mode==='common'"><section aria-label="常用 Java 诊断" class="arthas-presets"><Button v-for="item in arthasDiagnostics" :key="item.key" @click="diagnose(item.key)" variant="outline" size="default" type="button" :disabled="(!target||!!diagnosing||!!error||loading)||(diagnosing===item.key)"><Spinner v-if="diagnosing===item.key"/><span class="diagnostic-label"><strong>{{item.label}}</strong><small>{{item.description}}</small></span></Button></section><StatePanel v-if="diagnosticError" :error="true" title="本次诊断未完成" :message="diagnosticError"/><ArthasDiagnosticResult v-else-if="diagnosis" :result="diagnosis"/><Empty v-else><EmptyHeader><EmptyDescription>{{diagnosing?'正在采样，结果不会自动重试…':'选择实例和诊断项目即可开始；单次采样最长 10 秒。'}}</EmptyDescription></EmptyHeader></Empty></template><template v-else><section class="arthas-command"><div class="arthas-quick"><span>填入命令</span><Button v-for="text in arthasQuickCommands" :key="text" @click="command=text" variant="outline" size="sm" type="button" :disabled="(executing||confirming||disconnecting||!session||scopeChanged||uncertain)">{{text}}</Button></div><Textarea v-model="command" aria-label="Arthas 命令" :disabled="!session||executing||scopeChanged||uncertain" placeholder="输入 Arthas 命令，Ctrl + Enter 执行；快捷项仅填入，不会自动执行" @keydown.ctrl.enter.prevent="execute" :maxlength="4096" :rows="({minRows:2,maxRows:4}).minRows||4"/><div class="arthas-command-actions"><small>结果仅保留在当前窗口；最长 10 秒、输出上限 1 MiB。会话最长 15 分钟，空闲 5 分钟过期。</small><Button @click="interrupt" variant="outline" size="default" type="button" :disabled="(!session||(!executing&amp;&amp;!uncertain))||(interrupting)"><Spinner v-if="interrupting"/>中断当前命令</Button><Button @click="execute" variant="default" size="default" type="button" :disabled="(!session||!command.trim()||scopeChanged||uncertain)||(executing||confirming)"><Spinner v-if="executing||confirming"/>执行</Button></div></section></template><section v-if="mode==='advanced'" aria-label="Arthas 执行输出" aria-live="polite" class="arthas-output"><Empty v-if="!outputs.length"><EmptyHeader><EmptyDescription>{{"尚未执行命令；连接成功不代表应用健康。"}}</EmptyDescription></EmptyHeader></Empty><article v-for="item in outputs" :key="item.id"><div class="arthas-output-title"><code>{{item.command}}</code><Badge :variant="(item.state==='success'?'green':item.state==='executing'?'blue':'orange')==='red'?'destructive':'secondary'">{{arthasStateLabel(item.state)}}</Badge></div><small>{{item.target}} · {{item.message}}</small><pre v-if="item.output">{{item.output}}</pre></article></section></template><Dialog :open="editing" @update:open="async v=>{if(!v){editing=false;cancelConfig()}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(620px,calc(100vw - 24px))&quot;)==='number'?(&quot;min(620px,calc(100vw - 24px))&quot;)+'px':(&quot;min(620px,calc(100vw - 24px))&quot;)}" :show-close-button="!saving" @interact-outside="e=>{if(!(false))e.preventDefault()}" @escape-key-down="e=>{if(!(!saving))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>{{form.id?'编辑 Arthas 连接':'配置 Arthas 连接'}}</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><form ref="targetForm" @submit.prevent=""><fieldset  class="min-w-0 space-y-5" ><Field data-validation-field="name" :data-invalid="!!_validationErrors['name']" @vue:mounted="delete _validationErrors['name']"><FieldLabel>连接名称 <span class="text-destructive">*</span></FieldLabel><Input ref="nameInput" v-model="form.name" placeholder="例如：搜索服务 · 测试机 01" :maxlength="128"/><FieldError v-if="_validationErrors['name']">{{_validationErrors['name'].message}}</FieldError></Field><div class="arthas-form-columns"><Field data-validation-field="service" :data-invalid="!!_validationErrors['service']" @vue:mounted="delete _validationErrors['service']"><FieldLabel>应用标识 <span class="text-destructive">*</span></FieldLabel><Input ref="serviceInput" v-model="form.service" placeholder="例如：estate-ai-seek" :maxlength="128"/><FieldError v-if="_validationErrors['service']">{{_validationErrors['service'].message}}</FieldError></Field><Field data-validation-field="environment" :data-invalid="!!_validationErrors['environment']" @vue:mounted="delete _validationErrors['environment']"><FieldLabel>环境标识 <span class="text-destructive">*</span></FieldLabel><Input ref="environmentInput" v-model="form.environment" placeholder="例如：test" :maxlength="64"/><FieldError v-if="_validationErrors['environment']">{{_validationErrors['environment'].message}}</FieldError></Field></div><Field data-validation-field="endpoint" :data-invalid="!!_validationErrors['endpoint']" @vue:mounted="delete _validationErrors['endpoint']"><FieldLabel>Arthas HTTP 根地址 <span class="text-destructive">*</span></FieldLabel><Input ref="endpointInput" v-model="form.endpoint" placeholder="http://127.0.0.1:8563" :maxlength="2048"/><FieldDescription>地址需能从平台服务器访问。使用已有安全隧道或受控内网连接，不要直接向公网开放诊断端口。</FieldDescription><FieldError v-if="_validationErrors['endpoint']">{{_validationErrors['endpoint'].message}}</FieldError></Field><p v-if="formError" role="alert" class="arthas-warning">{{formError}}</p></fieldset></form><fieldset class="min-w-0 space-y-5" ><Field><FieldLabel>认证用户名</FieldLabel><Input v-model="form.credential_username" autocomplete="off" :maxlength="128"/></Field><Field><FieldLabel>认证密码（可选）</FieldLabel><Input v-model="form.credential_password" autocomplete="new-password" placeholder="留空不修改；不会回显原密码" :disabled="form.clear_credential" :max-length="4096" type="password"/><FieldDescription>仅在这里明确填写并保存，才会加密供常用诊断和 MCP 使用；留空保留原认证。改变地址、应用或环境会清除原认证。</FieldDescription></Field><FieldLabel class="flex items-center gap-2 font-normal" v-if="form.has_credential"><Checkbox  v-model="form.clear_credential" :disabled="!!form.credential_password"/>清除已保存认证</FieldLabel></fieldset></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button variant="outline" @click="async()=>{editing=false;cancelConfig()}" :disabled="({disabled:saving}).disabled">取消</Button><Button :disabled="saving" @click="async()=>{if(await (async()=>{await save();return false})()!==false){editing=false;}}"><Spinner v-if="saving"/>确认</Button></DialogFooter></DialogContent></Dialog><Dialog :open="auditOpen" @update:open="async v=>{if(!v){auditOpen=false;}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(940px,calc(100vw - 24px))&quot;)==='number'?(&quot;min(940px,calc(100vw - 24px))&quot;)+'px':(&quot;min(940px,calc(100vw - 24px))&quot;)}" :show-close-button="true" @interact-outside="e=>{e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>诊断审计 · 最近 100 条</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><StatePanel v-if="auditError" :error="true" :message="auditError"><Button @click="loadAudit" variant="outline" size="default" type="button">重试</Button></StatePanel><div class="min-w-0 max-w-full"><div v-if="auditLoading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:800}).y?({x:800}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:810}).x||({x:810}).minWidth||810)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(110)+'px'}">操作者</TableHead><TableHead :style="{width:(150)+'px'}">连接标识</TableHead><TableHead :style="{width:(140)+'px'}">操作</TableHead><TableHead :style="{width:(120)+'px'}">命令类型</TableHead><TableHead :style="{width:(110)+'px'}">状态</TableHead><TableHead :style="{width:(180)+'px'}">时间</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (audits||[])" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["actor"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(&quot;&quot;)}">{{record["target_id"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["action"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["command_name"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}">{{record["state"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]">{{new Date(record.at*1000).toLocaleString()}}</template></div></TableCell></TableRow></template><TableRow v-if="!(audits||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><p class="arthas-audit-note">仅记录操作者、目标、命令类型及摘要和结果状态，不保存命令正文、输出或认证密码。</p></div></DialogContent></Dialog><ArthasDeploymentConnect v-if="admin" ref="deploymentConnect" :service="service" :environment="environment" @connected="deploymentConnected" @busy="onboarding=$event"/></div></template>
